import com.bridger.momentum.*;
public class FailAttemptEvidenceRegression {
 static ReplayData.Frame pose(float pitch){return new ReplayData.Frame(.5,65,0,0,pitch,0,0,false,false,0,0,0,24,0);}
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args){FailAttemptEvidence e=new FailAttemptEvidence();e.placed(0,64,2);e.use(pose(0),true);e.use(pose(80),true);String first=e.summary();check(first.contains("too high"),"Later downward aim overwrote the actual first missed use");check(ReplayAimAnalysis.colored(first).startsWith("\u00a7a"),"High aim must be green");e.placed(0,64,3);check(e.summary().contains("No placement input"),"A later placement retained an old fail");e.placed(0,64,2);e.use(pose(80),true);check(e.summary().contains("too low")&&ReplayAimAnalysis.colored(e.summary()).startsWith("\u00a7c"),"Low aim must be red");e.placed(0,64,2);e.use(pose(45),true);check(e.summary().contains("uncertain"),"Valid aim invented an explanation");e.placed(0,64,2);e.use(pose(0),false);check(e.summary().equals("Not holding a block."),"Non-block use diagnosed as aim");e.placed(0,64,2);e.use(pose(45),true);e.target(0,65,0,0,false);check(e.summary().contains("collision"),"Body collision ignored");e.placed(0,64,2);e.use(pose(45),true);e.target(0,64,3,0,true);check(e.summary().contains("occupied"),"Occupied target ignored");e.placed(0,64,2);e.use(pose(45),true);e.target(0,66,3,1,false);check(e.summary().equals("Top face hit."),"Wrong face ignored");e.placed(0,64,2);e.use(pose(45),true);e.target(0,64,3,0,false);e.result(false);check(e.summary().equals("No client placement."),"Native result ignored");e.clear();check(e.summary().contains("Not enough"),"Old run evidence leaked");System.out.println("PASS use-time aim instead of later pose, placement reset, short colour-coded diagnosis and uncertainty");}
}
